create or replace function assign_asset_category_code()returns trigger language plpgsql set search_path=public,pg_temp as $$declare next_number bigint;begin if tg_op='UPDATE'then new.category_code:=old.category_code;return new;end if;if nullif(trim(new.category_code),'')is null or upper(trim(new.category_code))='AUTO'then perform pg_advisory_xact_lock(hashtextextended('asset-category-'||new.subsidiary_id,0));select coalesce(max(case when category_code~'^CAT-ACT-[0-9]+$'then substring(category_code from'[0-9]+$')::bigint end),0)+1 into next_number from asset_category where subsidiary_id=new.subsidiary_id;new.category_code:='CAT-ACT-'||lpad(next_number::text,6,'0');end if;return new;end$$;
drop trigger if exists asset_category_auto_code on asset_category;create trigger asset_category_auto_code before insert or update of category_code on asset_category for each row execute function assign_asset_category_code();
notify pgrst,'reload schema';
